package com.autoops.embedding;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;@Component public class HashEmbeddingProvider implements EmbeddingProvider{public float[] embed(String text){float[]v=new float[384];try{byte[]h=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));for(int i=0;i<v.length;i++)v[i]=(h[i%h.length]&255)/255f;}catch(Exception e){throw new IllegalStateException(e);}return v;}public String provider(){return "LOCAL";}public String model(){return "hash-dev-384";}}
